const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});nav.querySelectorAll('a,button').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation')}));
const dialog=document.getElementById('brief-dialog');document.querySelectorAll('[data-brief]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('brief-status').textContent='';dialog.querySelector('select').value=document.body.dataset.industry||'Defense';dialog.showModal()}));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.getElementById('brief-form').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const text=`ABSOLUTE OPERATIONS — APPLICATION BRIEF\n\nApplication: ${d.application}\nIndustry: ${d.industry}\nMaximum axial depth: ${d.depth||'To be defined'} mm\nContinuous torque: ${d.torque||'To be defined'} N·m\nOperating speed: ${d.speed||'To be defined'} RPM\n\nIntegration requirements:\n${d.requirements||'To be defined'}\n\nPrepared locally. This brief has not been submitted.\nCompany website: https://absoluteoperations.com/\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='absolute-operations-application-brief.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('brief-status').textContent='Your brief has been downloaded. Share it through your existing Absolute Operations contact.'});
document.getElementById('year').textContent=new Date().getFullYear();
const bolts=document.getElementById('bolts');for(let i=0;bolts&&i<12;i++){const a=i*Math.PI/6;const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx',String(Math.cos(a)*174));c.setAttribute('cy',String(Math.sin(a)*174));c.setAttribute('r','4');c.setAttribute('fill','#152a38');c.setAttribute('stroke','#b8c4cb');bolts.append(c)}
